using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class EnvironmentWorkspaceOperations
{
    private readonly TerrainCaveOperations _caves=new();
    private readonly EnvironmentCaveTool _caveEditor=new();
    private void EditCaves(Control owner,string id,Action<GArray> edit)
    {var terrain=_documents.terrain(Document(Session(owner)),id);if(terrain==null)return;var originals=terrain.Get("caves").AsGodotArray();var next=originals.Duplicate();next.Clear();foreach(var source in originals)next.Add(source.As<Resource>().Duplicate(true));edit(next);regenerate_terrain(owner,id,new Settings {["caves"]=next},false,false);}
    public void edit_caves(Control owner,string id,Settings edit)=>EditCaves(owner,id,next=>owner.Call("_invoke_source_edit",edit,next));
    public void replace_cave(Control owner,string id,Resource cave)=>EditCaves(owner,id,next=>{for(int index=0;index<next.Count;index++)if(next[index].As<Resource>().Get("cave_id").AsString()==cave.Get("cave_id").AsString()){next[index]=cave;return;}next.Add(cave);});
    public void add_cave(Control owner,int kind)
    {
        var session=Session(owner);var document=Document(session);var item=session.Call("primary").As<Resource>();if(item==null||_documents.terrain(document,item.Get("id").AsString())==null)foreach(var value in document.Get("components").AsGodotArray()){var candidate=value.As<Resource>();if(_documents.terrain(document,candidate.Get("id").AsString())!=null){item=candidate;break;}}
        var terrain=item==null?null:_documents.terrain(document,item.Get("id").AsString());if(terrain==null){Status(owner,"Add or select a terrain first.");return;}string id=item!.Get("id").AsString();var dimensions=terrain.Get("dimensions").AsVector2();var origin=new Vector2(0,-dimensions.Y*.3f);var surface=terrain.Call("sample",origin).AsGodotDictionary();var entrance=new Vector3(origin.X,Get(surface,"height",0.0).AsSingle()+.5f,origin.Y);var cave=_caves.network(entrance,6,Math.Min(16,dimensions.Y*.4),kind==0?2:0,terrain.Get("seed").AsInt64()+terrain.Get("caves").AsGodotArray().Count*137);
        if(kind==1){cave.Set("title","Tunnel");cave.Set("chambers",Array.Empty<Vector4>());}else if(kind==2){cave.Set("title","Chamber");cave.Get("paths").AsGodotArray().Clear();cave.Set("chambers",new[]{new Vector4(entrance.X,entrance.Y-6,entrance.Z,3)});}
        string caveId=cave.Get("cave_id").AsString();State(owner,"_expanded_landforms")[caveId]=true;var canvas=Field<Control>(owner,"canvas");canvas.Get("cave_tool").As<RefCounted>().Set("cave_id",caveId);session.Call("select",id);EditCaves(owner,id,next=>next.Add(cave));canvas.Set("environment_tool","Cave path");canvas.Get("renderer").As<Node3D>().Set("cave_cutaway",true);refresh_context(owner);
    }
    public void cave_properties(Control owner,Resource item,Resource terrain)
    {
        string id=item.Get("id").AsString();var parent=Field<VBoxContainer>(owner,"properties");var canvas=Field<Control>(owner,"canvas");var editor=canvas.Get("cave_tool").As<RefCounted>();Button(parent,"＋ Cave network",()=>add_cave(owner,0));var caves=terrain.Get("caves").AsGodotArray();if(caves.Count==0)return;
        Number(parent,"Vertical voxel size",terrain.Get("voxel_height").AsDouble(),.1,4,.1,value=>regenerate_terrain(owner,id,new Settings {["voxel_height"]=value},false,false));Number(parent,"Voxel cell budget",terrain.Get("voxel_cell_budget").AsDouble(),1000,2000000,1000,value=>regenerate_terrain(owner,id,new Settings {["voxel_cell_budget"]=(long)value},false,false));Button(parent,"Regenerate cave geometry",()=>regenerate_terrain(owner,id,new Settings(),false,true));Button(parent,"Density slice…",()=>{var slice=new TerrainSliceView {source=terrain};owner.AddChild(slice);slice.PopupCentered(new Vector2I(660,480));});
        for(int index=0;index<caves.Count;index++)
        {
            int slot=index;var cave=caves[index].As<Resource>();string caveId=cave.Get("cave_id").AsString();var row=new HBoxContainer();parent.AddChild(row);var enabled=new CheckBox {ButtonPressed=cave.Get("enabled").AsBool()};row.AddChild(enabled);enabled.Toggled+=value=>EditCaves(owner,id,next=>next[slot].As<Resource>().Set("enabled",value));ExpandButton(owner,row,cave.Get("title").AsString(),caveId);Button(row,"Edit",()=>{editor.Set("cave_id",caveId);canvas.Set("environment_tool","Cave path");canvas.Get("renderer").As<Node3D>().Set("cave_cutaway",true);canvas.Call("request_sync");refresh_context(owner);canvas.GrabFocus();});Button(row,"×",()=>EditCaves(owner,id,next=>next.RemoveAt(slot)));if(!Get(State(owner,"_expanded_landforms"),caveId,false).AsBool())continue;
            var name=new LineEdit {Text=cave.Get("title").AsString(),PlaceholderText="Cave name"};parent.AddChild(name);name.TextSubmitted+=value=>EditCaves(owner,id,next=>next[slot].As<Resource>().Set("title",value));foreach(var spec in new[]{("Tunnel radius","radius",.1,50.0,.1),("Radius variation","radius_variation",0.0,.5,.01),("Smooth joins","junction_smoothing",0.0,5.0,.1),("Wall roughness","roughness",0.0,2.0,.01),("Detail frequency","detail_frequency",.01,5.0,.01),("Detail seed","seed",-100000.0,100000.0,1.0)})Number(parent,spec.Item1,cave.Get(spec.Item2).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>EditCaves(owner,id,next=>next[slot].As<Resource>().Set(spec.Item2,spec.Item2=="seed"?Variant.From((long)value):Variant.From(value))));
            var selected=new OptionButton {FitToLongestItem=false};parent.AddChild(selected);var handles=new List<(int Path,int Point,Vector3 Position)>();var paths=cave.Get("paths").AsGodotArray();for(int path=0;path<paths.Count;path++){var points=paths[path].AsVector3Array();for(int point=0;point<points.Length;point++){handles.Add((path,point,points[point]));selected.AddItem("Tunnel "+(path+1)+" · point "+(point+1));}}var chambers=cave.Get("chambers").AsVector4Array();for(int point=0;point<chambers.Length;point++){var chamber=chambers[point];handles.Add((-1,point,new Vector3(chamber.X,chamber.Y,chamber.Z)));selected.AddItem("Chamber "+(point+1));}
            int chosen=0;for(int handle=0;handle<handles.Count;handle++)if(caveId==editor.Get("cave_id").AsString()&&handles[handle].Path==editor.Get("path_index").AsInt32()&&handles[handle].Point==editor.Get("point_index").AsInt32()){chosen=handle;break;}selected.Select(handles.Count>0?chosen:-1);selected.ItemSelected+=which=>{var handle=handles[(int)which];editor.Set("cave_id",caveId);editor.Set("path_index",handle.Path);editor.Set("point_index",handle.Point);refresh_properties(owner);canvas.Get("overlay").As<Control>().QueueRedraw();};
            if(handles.Count>0){var handle=handles[chosen];for(int axis=0;axis<3;axis++){int component=axis;Number(parent,"Point "+new[]{"X","Y","Z"}[axis],handle.Position[axis],-10000,10000,.1,value=>EditCaves(owner,id,next=>{var point=handle.Position;point[component]=(float)value;_caveEditor.set_point(next[slot].As<Resource>(),handle.Path,handle.Point,point);}));}if(handle.Path<0)Number(parent,"Chamber radius",chambers[handle.Point].W,.1,50,.1,value=>EditCaves(owner,id,next=>{var target=next[slot].As<Resource>();var points=target.Get("chambers").AsVector4Array();points[handle.Point].W=(float)value;target.Set("chambers",points);}));}
            Button(parent,"Clear dig / fill edits",()=>EditCaves(owner,id,next=>next[slot].As<Resource>().Get("edits").AsGodotArray().Clear()));
        }
    }
}
